def blade_product(a, b, metric):
    sign = 1
    for i, square in enumerate(metric):
        if a & (1 << i):
            for j in range(i):
                if b & (1 << j):
                    sign = -sign
            if b & (1 << i):
                sign *= square
    return a ^ b, sign

def gp(a, b, metric=(1, 1, 1)):
    size = 1 << len(metric)
    assert len(a) == len(b) == size
    out = [0.0] * size
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            k, sign = blade_product(i, j, metric)
            out[k] += sign * ai * bj
    return out

# Bit-mask order: 1, e1, e2, e12, e3, e13, e23, e123

from math import cos, sin, pi

def reverse(a):
    return [x * (-1) ** (i.bit_count() * (i.bit_count()-1) // 2)
            for i, x in enumerate(a)]

def rotor(theta):
    return [cos(theta/2), 0, 0, -sin(theta/2), 0, 0, 0, 0]

R = rotor(pi/2)
e1 = [0, 1, 0, 0, 0, 0, 0, 0]
v = gp(gp(R, e1), reverse(R))
# v is e2, up to floating-point rounding
